urlset:
{{- $news := where (where site.RegularPages "Section" "notas") "Params.news" true -}}
{{- $recent := where $news "Date" "ge" (now.AddDate 0 0 -2) }}
{{- range first 1000 $recent.ByDate.Reverse }}

    {{ .Permalink | htmlEscape }}


        {{ site.Title | htmlEscape }}
        {{ site.Language.Lang }}

      {{ .Date.Format "2006-01-02T15:04:05Z07:00" }}
      {{ .Title | plainify | htmlEscape }}


{{- end }}
